      width: { type: 'number', group: 'Shape', label: 'Cable width', default: 0.018, min: 0.002, max: 0.05, step: 0.001 },
      seed: { type: 'number', group: 'Shape', label: 'Arrangement', default: 7, min: 0, max: 999, step: 1 },
